    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    cells=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0: cells.append((r,c,grid[r][c]))
    if not cells:return out
    c0=round(sum(x[1] for x in cells)/len(cells)); vals=[x[2] for x in cells]
    n=len(vals); k=1
    while k*(k+1)//2<=n: k+=1
    # expected triangular count, use rows widths odd
    widths=[2*i+1 for i in range(k)]
    if sum(widths)>n: k-=1; widths=widths[:-1]
    pos=0
    for j,ww in enumerate(widths):
        color=vals[pos]; pos+=ww
        rr=h-k+j
        for cc in range(c0-ww//2,c0+ww//2+1):
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=color
    return out"}

